using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Globalization;
using System.IO;
using System.Text;
using System.Web.Script.Serialization;
using System.Windows.Forms;
using Microsoft.Win32;

internal static class Program
{
    private const string Version="3.7.0";
    private static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
    private static readonly string NativeDir=AppDomain.CurrentDomain.BaseDirectory.TrimEnd(Path.DirectorySeparatorChar);
    private static readonly string InstallRoot=Directory.GetParent(NativeDir).FullName;
    private static readonly string ToolsDir=Path.Combine(InstallRoot,"tools"),ConfigDir=Path.Combine(InstallRoot,"config"),RuntimeDir=Path.Combine(InstallRoot,"runtime"),LogDir=Path.Combine(RuntimeDir,"logs"),SettingsPath=Path.Combine(ConfigDir,"settings.json");

    [STAThread] private static void Main(){try{CleanupStaleFiles();var r=ReadRequest(Console.OpenStandardInput());var a=GetString(r,"action");if(a=="ping"){WriteResponse(BuildPing());return;}if(a=="getConfig"){WriteResponse(ConfigResponse("getConfig",false));return;}if(a=="chooseDownloadDirectory"){WriteResponse(ChooseDirectory());return;}if(a=="resetDownloadDirectory"){var p=ValidateDirectory(GetDefaultDownloadDirectory(),true);WriteSettings(p);WriteResponse(ConfigResponse("resetDownloadDirectory",true));return;}if(a=="validate"){if(GetString(r,"protocolVersion")=="2")ValidateDownloadRequest(r);else ValidateUrl(GetString(r,"url"));WriteResponse(new Dictionary<string,object>{{"ok",true},{"phase","validated"}});return;}if(a!="download")throw new InvalidDataException("Unsupported native action");ValidateDownloadRequest(r);ValidateDirectory(ReadDownloadDirectory(),true);var worker=Path.Combine(NativeDir,"yt-dlp-worker.ps1");if(!File.Exists(worker))throw new FileNotFoundException("Download worker not found",worker);var requestDir=Path.Combine(RuntimeDir,"requests");Directory.CreateDirectory(requestDir);var requestPath=Path.Combine(requestDir,"request-"+Guid.NewGuid().ToString("N")+".json");File.WriteAllText(requestPath,Json.Serialize(r),new UTF8Encoding(false));var ps=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"WindowsPowerShell","v1.0","powershell.exe");var si=new ProcessStartInfo{FileName=ps,Arguments="-NoProfile -ExecutionPolicy Bypass -File "+Quote(worker)+" -RequestFile "+Quote(requestPath),UseShellExecute=true,WindowStyle=ProcessWindowStyle.Normal,WorkingDirectory=NativeDir};var proc=Process.Start(si);if(proc==null)throw new InvalidOperationException("PowerShell worker did not start");WriteLog("download-started site="+GetString(r,"site")+" pid="+proc.Id);WriteResponse(new Dictionary<string,object>{{"ok",true},{"phase","started"},{"message","本地下载窗口已启动"}});}catch(Exception ex){WriteLog("host-error "+ex.GetType().Name+": "+ex.Message);WriteResponse(new Dictionary<string,object>{{"ok",false},{"phase","failed"},{"error",ex.Message}});}}

    private static object ChooseDirectory(){var current=ReadDownloadDirectory();using(var d=new FolderBrowserDialog()){d.Description="请选择视频下载保存文件夹";d.ShowNewFolderButton=true;if(Directory.Exists(current))d.SelectedPath=current;var result=d.ShowDialog();if(result!=DialogResult.OK)return new Dictionary<string,object>{{"ok",true},{"cancelled",true},{"downloadDirectory",current}};var selected=ValidateDirectory(d.SelectedPath,true);WriteSettings(selected);return ConfigResponse("chooseDownloadDirectory",false);}}
    private static object ConfigResponse(string action,bool reset){var p=ValidateDirectory(ReadDownloadDirectory(),true);var result=new Dictionary<string,object>{{"ok",true},{"action",action},{"schemaVersion",1},{"downloadDirectory",p},{"downloadDirectoryWritable",true},{"isDefault",String.Equals(p,ValidateDirectory(GetDefaultDownloadDirectory(),true),StringComparison.OrdinalIgnoreCase)}};if(reset)result["reset"]=true;return result;}
    private static object BuildPing(){string worker=Path.Combine(NativeDir,"yt-dlp-worker.ps1"),y=Path.Combine(ToolsDir,"yt-dlp.exe"),f=Path.Combine(ToolsDir,"ffmpeg.exe"),d=Path.Combine(ToolsDir,"deno.exe"),p=ValidateDirectory(ReadDownloadDirectory(),true);var ok=File.Exists(worker)&&File.Exists(y)&&File.Exists(f)&&File.Exists(d);return new Dictionary<string,object>{{"ok",ok},{"phase","ready"},{"version",Version},{"worker",File.Exists(worker)},{"ytdlp",File.Exists(y)},{"ffmpeg",File.Exists(f)},{"deno",File.Exists(d)},{"downloadDirectory",p},{"downloadDirectoryWritable",true}};}

    private static string GetDefaultDownloadDirectory(){try{using(var k=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders")){var v=k==null?null:k.GetValue("{374DE290-123F-4565-9164-39C4925E467B}") as string;if(!String.IsNullOrWhiteSpace(v))return Path.Combine(Environment.ExpandEnvironmentVariables(v),"yt-dlp");}}catch{}return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Downloads","yt-dlp");}
    private static string ReadDownloadDirectory(){if(!File.Exists(SettingsPath))return GetDefaultDownloadDirectory();var settings=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(SettingsPath,Encoding.UTF8));string schema=GetString(settings,"schemaVersion"),p=GetString(settings,"downloadDirectory");if(schema!="1"||String.IsNullOrWhiteSpace(p))throw new InvalidDataException("settings.json is invalid");return p;}
    private static void WriteSettings(string path){Directory.CreateDirectory(ConfigDir);var temp=Path.Combine(ConfigDir,"settings."+Guid.NewGuid().ToString("N")+".tmp");try{var obj=new Dictionary<string,object>{{"schemaVersion",1},{"downloadDirectory",path}};using(var fs=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){var data=new UTF8Encoding(false).GetBytes(Json.Serialize(obj));fs.Write(data,0,data.Length);fs.Flush(true);}if(File.Exists(SettingsPath)){var backup=SettingsPath+".bak";try{File.Replace(temp,SettingsPath,backup,true);if(File.Exists(backup))File.Delete(backup);}catch{File.Delete(SettingsPath);File.Move(temp,SettingsPath);}}else File.Move(temp,SettingsPath);}finally{if(File.Exists(temp))try{File.Delete(temp);}catch{}}}
    private static string ValidateDirectory(string value,bool probe){if(String.IsNullOrWhiteSpace(value)||value.IndexOf('\0')>=0||value.StartsWith(@"\\")||value.StartsWith(@"\\?\")||value.StartsWith(@"\\.\"))throw new InvalidDataException("所选目录必须是本机磁盘上的绝对路径");var full=Path.GetFullPath(value).TrimEnd(Path.DirectorySeparatorChar);var root=Path.GetPathRoot(full).TrimEnd(Path.DirectorySeparatorChar);if(String.IsNullOrEmpty(root)||full.Length>220||String.Equals(full,root,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("不能选择磁盘根目录");var userRoot=Environment.GetFolderPath(Environment.SpecialFolder.UserProfile).TrimEnd(Path.DirectorySeparatorChar);var localRoot=Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData).TrimEnd(Path.DirectorySeparatorChar);if(String.Equals(full,userRoot,StringComparison.OrdinalIgnoreCase)||String.Equals(full,localRoot,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("不能直接选择用户目录或 LocalAppData 根目录");foreach(var forbidden in ForbiddenTrees()){if(IsSameOrChild(full,forbidden))throw new InvalidDataException("该目录属于系统或程序目录，不能作为下载目录");}var existing=full;while(!Directory.Exists(existing)){var parent=Path.GetDirectoryName(existing);if(String.IsNullOrEmpty(parent)||parent==existing)break;existing=parent;}for(var p=existing;!String.IsNullOrEmpty(p);p=Path.GetDirectoryName(p)){try{if((File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("不能选择符号链接或目录联接");}catch(DirectoryNotFoundException){}if(String.Equals(p,Path.GetPathRoot(p),StringComparison.OrdinalIgnoreCase))break;}Directory.CreateDirectory(full);if(probe){var test=Path.Combine(full,".write-test-"+Guid.NewGuid().ToString("N"));try{File.WriteAllText(test,"ok");}finally{if(File.Exists(test))File.Delete(test);}}return full;}
    private static IEnumerable<string> ForbiddenTrees(){yield return InstallRoot;yield return Environment.GetFolderPath(Environment.SpecialFolder.Windows);yield return Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles);yield return Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86);yield return Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData);}
    private static bool IsSameOrChild(string p,string root){if(String.IsNullOrWhiteSpace(root))return false;root=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar);return String.Equals(p,root,StringComparison.OrdinalIgnoreCase)||p.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase);}

    private static void ValidateDownloadRequest(Dictionary<string,object> r){string site=GetString(r,"site"),mode=GetString(r,"mode"),page=GetString(r,"sourcePageUrl"),media=GetString(r,"mediaUrl");if(site=="xinpianchang"){if(mode!="extractor"||!IsXinpianchang(page)||!String.IsNullOrEmpty(media))throw new InvalidDataException("新片场仅支持作品详情页");ValidateCookies(r,".xinpianchang.com");return;}if(site=="liblib"){if(mode!="direct-public-mp4"||!IsLiblibPage(page)||!IsLiblibMedia(media)||CookieCount(r)!=0)throw new InvalidDataException("Liblib 仅支持公开 MP4 作品");return;}if(site=="kuaishou"){if(mode!="direct-public-mp4"||!IsKuaishouPage(page)||!IsKuaishouMedia(media)||CookieCount(r)!=0)throw new InvalidDataException("快手仅支持公开视频");return;}if(mode!="extractor")throw new InvalidDataException("Invalid download request");ValidateUrl(page);}
    private static bool IsXinpianchang(string value){Uri u;return Uri.TryCreate(value,UriKind.Absolute,out u)&&u.Scheme==Uri.UriSchemeHttps&&u.Host=="www.xinpianchang.com"&&System.Text.RegularExpressions.Regex.IsMatch(u.AbsolutePath,@"^/a\d+$");}
    private static bool IsLiblibPage(string value){Uri u;return Uri.TryCreate(value,UriKind.Absolute,out u)&&u.Scheme==Uri.UriSchemeHttps&&(u.Host=="www.liblib.tv"||u.Host.EndsWith(".liblib.tv"));}
    private static bool IsLiblibMedia(string value){Uri u;return Uri.TryCreate(value,UriKind.Absolute,out u)&&u.Scheme==Uri.UriSchemeHttps&&u.Host=="libtv-res.liblib.art"&&String.IsNullOrEmpty(u.UserInfo)&&u.IsDefaultPort&&u.AbsolutePath.EndsWith(".mp4",StringComparison.OrdinalIgnoreCase);}
    private static bool IsKuaishouPage(string value){Uri u;return Uri.TryCreate(value,UriKind.Absolute,out u)&&u.Scheme==Uri.UriSchemeHttps&&(u.Host=="kuaishou.com"||u.Host.EndsWith(".kuaishou.com"));}
    private static bool IsKuaishouMedia(string value){Uri u;if(!(Uri.TryCreate(value,UriKind.Absolute,out u)&&u.Scheme==Uri.UriSchemeHttps&&String.IsNullOrEmpty(u.UserInfo)&&u.IsDefaultPort))return false;string h=u.Host.ToLowerInvariant();foreach(string d in new[]{"ndcimgs.com","kwaivideo.com","yximgs.com","kwimgs.com","gifshow.com"}){if(h==d||h.EndsWith("."+d))return u.AbsolutePath.EndsWith(".mp4",StringComparison.OrdinalIgnoreCase);}return false;}
    private static int CookieCount(Dictionary<string,object> r){object v;if(!r.TryGetValue("cookies",out v)||v==null)return 0;var a=v as System.Collections.ArrayList;if(a!=null)return a.Count;var arr=v as object[];return arr==null?0:arr.Length;}
    private static void ValidateCookies(Dictionary<string,object> r,string domain){object v;if(!r.TryGetValue("cookies",out v)||v==null)return;var a=v as System.Collections.ArrayList;if(a==null||a.Count>500)throw new InvalidDataException("Invalid browser cookies");foreach(var item in a){var c=item as Dictionary<string,object>;var d=GetString(c,"domain");if(!(d=="xinpianchang.com"||d==domain))throw new InvalidDataException("Invalid cookie domain");}}
    private static void ValidateUrl(string value){Uri u;if(!Uri.TryCreate(value,UriKind.Absolute,out u)||u.Scheme!=Uri.UriSchemeHttps)throw new InvalidDataException("Only HTTPS video URLs are allowed");var h=u.Host.ToLowerInvariant();if(!(h=="douyin.com"||h.EndsWith(".douyin.com")||h=="bilibili.com"||h.EndsWith(".bilibili.com")||h=="youtube.com"||h.EndsWith(".youtube.com")||h=="youtu.be"||h=="xiaohongshu.com"||h.EndsWith(".xiaohongshu.com")||h=="xhslink.com"||h.EndsWith(".xhslink.com")||h=="x.com"||h.EndsWith(".x.com")||h=="twitter.com"||h.EndsWith(".twitter.com")||h=="instagram.com"||h.EndsWith(".instagram.com")||h=="tiktok.com"||h.EndsWith(".tiktok.com")))throw new InvalidDataException("Only supported video-site URLs are allowed");if((h=="x.com"||h.EndsWith(".x.com")||h=="twitter.com"||h.EndsWith(".twitter.com"))&&!System.Text.RegularExpressions.Regex.IsMatch(u.AbsolutePath,@"^/(?:[^/]+|i)/status/\d+"))throw new InvalidDataException("Please open a specific X/Twitter status page");if((h=="instagram.com"||h.EndsWith(".instagram.com"))&&!System.Text.RegularExpressions.Regex.IsMatch(u.AbsolutePath,@"^/(?:p|reel|reels|tv)/[A-Za-z0-9_-]{5,}"))throw new InvalidDataException("Please open a specific Instagram post or reel page");if((h=="tiktok.com"||h.EndsWith(".tiktok.com"))&&!System.Text.RegularExpressions.Regex.IsMatch(u.AbsolutePath,@"^/@[A-Za-z0-9._-]+/video/\d+"))throw new InvalidDataException("Please open a specific TikTok video page");}
    private static Dictionary<string,object> ReadRequest(Stream input){var l=ReadExact(input,4);if(l==null)throw new EndOfStreamException("Native message is empty");var n=BitConverter.ToInt32(l,0);if(n<=0||n>2*1024*1024)throw new InvalidDataException("Invalid native message length");var b=ReadExact(input,n);if(b==null)throw new EndOfStreamException("Native message is truncated");var r=Json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(b));if(r==null)throw new InvalidDataException("Native message is not a JSON object");return r;}
    private static string GetString(Dictionary<string,object> v,string k){object i;return v!=null&&v.TryGetValue(k,out i)&&i!=null?Convert.ToString(i,CultureInfo.InvariantCulture):"";}
    private static void CleanupStaleFiles(){foreach(var f in new[]{"requests","cookies"}){var p=Path.Combine(RuntimeDir,f);if(!Directory.Exists(p))continue;foreach(var x in Directory.GetFiles(p))try{if(File.GetLastWriteTimeUtc(x)<DateTime.UtcNow.AddHours(-24))File.Delete(x);}catch{}}}
    private static string Quote(string v){return"\""+v.Replace("\"","\\\"")+"\"";}private static byte[] ReadExact(Stream s,int n){var b=new byte[n];var o=0;while(o<n){var r=s.Read(b,o,n-o);if(r==0)return null;o+=r;}return b;}private static void WriteLog(string m){try{Directory.CreateDirectory(LogDir);File.AppendAllText(Path.Combine(LogDir,"native-host.log"),DateTime.Now.ToString("s")+" "+m+Environment.NewLine,Encoding.UTF8);}catch{}}private static void WriteResponse(object r){var b=Encoding.UTF8.GetBytes(Json.Serialize(r));var o=Console.OpenStandardOutput();var l=BitConverter.GetBytes(b.Length);o.Write(l,0,l.Length);o.Write(b,0,b.Length);o.Flush();}
}
